"""Header values (tokens the user pasted) are stored encrypted. The key is a secret of the deployment (``MCP_ENCRYPTION_KEY``, generated by
``deploy.sh setup`` into Secret Manager); a database dump alone cannot reveal anyone's tokens. Rotating the key makes saved headers unreadable
(the user pastes them again)."""
from __future__ import annotations

import json

from cryptography.fernet import Fernet, InvalidToken

KEY_NAME = "MCP_ENCRYPTION_KEY"


class McpUnavailable(RuntimeError):
    """MCP cannot be used right now (no encryption key, or the policy has it off)."""


def generate_key() -> str:
    return Fernet.generate_key().decode()


class HeaderCipher:
    def __init__(self, key: str):
        try:
            self._f = Fernet(key.encode() if isinstance(key, str) else key)
        except (ValueError, TypeError) as exc:
            raise McpUnavailable(f"{KEY_NAME} is not a valid key (make one with: python -c 'from pinboard.mcp import generate_key; print(generate_key())')") from exc

    def encrypt(self, headers: dict[str, str]) -> str:
        return self._f.encrypt(json.dumps(headers, separators=(",", ":")).encode()).decode() if headers else ""

    def decrypt(self, token: str) -> dict[str, str]:
        if not token:
            return {}
        try:
            return json.loads(self._f.decrypt(token.encode()))
        except (InvalidToken, ValueError) as exc:
            raise McpUnavailable("the saved headers cannot be read with the current encryption key; save the server again") from exc


def cipher_from_vault(vault) -> HeaderCipher:
    key = vault.get(KEY_NAME)
    if not key:
        raise McpUnavailable(f"{KEY_NAME} is not set, so MCP server tokens cannot be stored safely")
    return HeaderCipher(key)
